 return new Map(['PRE_RELEASE','POST_RELEASE'].flatMap(phase=>[...registerFixedScenario({scenario:'UT',phase,catalog:catalog.filter(c=>c.phase===phase),routes:Object.fromEntries(Object.entries(handlers).filter(([id])=>(id==='UT24'?'POST_RELEASE':'PRE_RELEASE')===phase).map(([id,handler])=>[id,{handler,...(id==='UT24'?{evidenceDependsOn:['E21.journey']}: {})}])),execute:context=>executeUsageAcceptance(context.selectionRef,context)})]));
