// Usage continuity collectors are callable, additive, and import safe. Their
// source guards are never actual Host, installation, or formal case evidence.
export const usageContinuityCases=Object.freeze(['UT07','UT16','UT19','UT22','UT23','UT24']);
const uCanonical=v=>JSON.stringify(v&&typeof v==='object'?Array.isArray(v)?v.map(x=>JSON.parse(uCanonical(x))):Object.fromEntries(Object.keys(v).sort().map(k=>[k,JSON.parse(uCanonical(v[k]))])):v);
