const uExact=(v,required,optional=[])=>{assert(v&&typeof v==='object'&&!Array.isArray(v));exact(v,required,optional);};
function uPin(pin,max=8388608){uExact(pin,['ref','sha256']);assert(/^[a-f0-9]{64}$/.test(pin.sha256));const b=usageRegular(pin.ref,max),s=fs.lstatSync(pin.ref);assert.equal(s.uid,process.getuid());assert.equal(s.mode&0o777,0o600);assert.equal(sha(b),pin.sha256);return b;}
function uJson(ref){return JSON.parse(usageRegular(ref,8388608));}
export function usageContinuityBudget(fixture,now=Date.now){
 assert(Number.isSafeInteger(fixture.maxRequests)&&fixture.maxRequests>0&&fixture.maxRequests<=2048);
 const start=now(),deadline=Math.min(start+540000,Date.parse(fixture.deadlineAt));let calls=0;
 const remaining=(cap=30000)=>{const left=deadline-now();assert(Number.isFinite(left)&&left>0,'NOT_READY: original usage continuity deadline exhausted');assert(Number.isSafeInteger(cap)&&cap>0);return Math.max(1,Math.min(cap,left));};
 return{deadline,remaining,take(){remaining();assert(++calls<=fixture.maxRequests,'NOT_READY: original usage request budget exhausted');},get calls(){return calls;}};
}
export function assertUsageContinuityPhase(caseId,phase){assert(usageContinuityCases.includes(caseId));assert.equal(phase,caseId==='UT24'?'POST_RELEASE':'PRE_RELEASE','POST evidence cannot satisfy a PRE case');}
